WITH remaining_keys AS (SELECT status, customer_id FROM orders INTERSECT SELECT status, customer_id FROM orders WHERE store_id IS NOT NULL), verified AS (SELECT s.* FROM orders s JOIN remaining_keys k ON s.status = k.status AND s.customer_id = k.customer_id) SELECT CASE WHEN shipping_fee >= 30 THEN 'PREMIUM' ELSE 'STANDARD' END AS shipping_fee_tier, COUNT(CASE WHEN channel = 'store' THEN 1 END) AS store_count, CORR(discount, amount) AS corr_discount_amount, MAX(discount) FILTER (WHERE status = 'SHIPPED') AS shipped_max_discount FROM verified GROUP BY shipping_fee_tier HAVING CORR(discount, amount) > 0 ORDER BY shipped_max_discount DESC NULLS FIRST
